#!/usr/bin/env python3
"""Inline mcp/front.py + mcp/tools.py (+ the page in web/) into the front service's `command` in
runtipi/docker-compose.yml, and write app/front.py (the same program, used by app/Dockerfile for `wam verify`).

Usage: python3 mcp/inline.py [--check]
The front runs on a stock, digest-pinned python image, so the app needs no image build or registry.
--check exits 1 when a generated file is out of date (CI uses this).
"""
import base64
import re
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
compose = root / "runtipi" / "docker-compose.yml"
single = root / "app" / "front.py"
WEB = ["index.html", "app.js", "styles.css", "boot.js", "wizard-tokens.css", "wizard-ui.css", "standalone.css",
       "standalone-tokens.css", "wizard-sheet.js"]
src = (root / "mcp" / "front.py").read_text() + "\n\n# ---- tools for this app ----\n" + (root / "mcp" / "tools.py").read_text()
# The page ships base64-wrapped so a dollar sign in CSS/JS never reaches compose interpolation.
vendor = {name: base64.b64encode((root / "web" / name).read_bytes()).decode() for name in WEB}
src += "\n\n# ---- the Wizard page (generated by mcp/inline.py from web/) ----\nVENDOR = " + repr(vendor) + "\n"
src += "\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n"
assert "$" not in src, "keep $ out of the MCP front (compose would interpolate it)"
text = compose.read_text()
pat = re.compile(r"^( *)# BEGIN MCP FRONT \(generated by mcp/inline.py\)\n\1- \|\n(.*?)\n\1# END MCP FRONT", re.S | re.M)
m = pat.search(text)
if not m:
    sys.exit("compose has no MCP FRONT markers")
ind = m.group(1)
block = "\n".join((ind + "  " + line) if line else "" for line in src.splitlines())
new = text[:m.start()] + f"{ind}# BEGIN MCP FRONT (generated by mcp/inline.py)\n{ind}- |\n{block}\n{ind}# END MCP FRONT" + text[m.end():]
if "--check" in sys.argv:
    stale = [str(p.relative_to(root)) for p, want in ((compose, new), (single, src))
             if not p.exists() or p.read_text() != want]
    sys.exit(("stale: " + ", ".join(stale) + " (run python3 mcp/inline.py)") if stale else 0)
compose.write_text(new)
single.write_text(src)
print("updated", compose.relative_to(root), "and", single.relative_to(root))
